-- -----------------------------------
-- Table structure for `down_communication`
-- -----------------------------------

DROP TABLE IF EXISTS `down_communication`;
CREATE TABLE `down_communication` (
  `sr_no` int(11) NOT NULL AUTO_INCREMENT,
  `atm_id` varchar(50) NOT NULL,
  `panel_id` varchar(50) NOT NULL,
  `dc_date` datetime DEFAULT NULL,
  PRIMARY KEY (`sr_no`)
) ENGINE=MyISAM AUTO_INCREMENT=5724 DEFAULT CHARSET=latin1;

